import { describe, it } from "vitest";

describe("MHPCO quote -- base premiums per item type", () => {
  it.todo("charges only the 5 G processing fee for an empty item list -- premium 5 G");
  it.todo("charges a sword at base premium 100 G -- premium 115 G for a new customer");
  it.todo("charges an amulet at base premium 60 G -- premium 71 G for a new customer");
  it.todo("charges a staff at base premium 80 G -- premium 93 G for a new customer");
  it.todo("charges a potion at base premium 40 G -- premium 49 G for a new customer");
  it.todo("charges a rune at base premium 25 G -- premium 33 G for a new customer");
  it.todo("charges a moonstone at base premium 25 G -- premium 33 G for a new customer");
  it.todo("rejects an unknown item type with an Error -- quote of {type: 'broomstick'} throws");
});

describe("MHPCO quote -- component building block of 3 alike components", () => {
  it.todo("charges 2 runes at 50 G base premium (no block)");
  it.todo("charges 3 runes at 60 G base premium (block applies)");
  it.todo("charges 4 runes at 100 G base premium (no block -- block requires exactly 3)");
  it.todo("charges 7 runes at 175 G base premium (no block -- block requires exactly 3)");
  it.todo("charges 2 runes + 1 moonstone at 75 G base premium (no block -- different types)");
  it.todo("charges 3 runes + 3 moonstones at 120 G base premium (two separate blocks)");
});

describe("MHPCO quote -- item-specific premium modifiers", () => {
  it.todo("adds a 50 % curse surcharge to a cursed sword -- base 100 G becomes 150 G");
  it.todo("adds a 30 % surcharge to a sword with enchantment exactly 5 -- base 100 G becomes 130 G");
  it.todo("adds no high-enchantment surcharge to a sword with enchantment 4 -- base stays 100 G");
  it.todo("adds both surcharges to a cursed sword with enchantment exactly 5 -- base 100 G becomes 180 G");
  it.todo("applies the curse surcharge only to the cursed item on a multi-item policy -- cursed sword + plain amulet base 160 G becomes 210 G");
});

describe("MHPCO quote -- policy-wide premium modifiers", () => {
  it.todo("grants a 20 % loyalty discount at exactly 2 years with MHPCO -- sword base 100 G becomes 80 G");
  it.todo("grants no loyalty discount at 1 year with MHPCO -- sword base stays 100 G");
  it.todo("adds a 10 % first insurance surcharge on the first quote -- sword base 100 G becomes 110 G");
  it.todo("grants a 15 % follow-up discount on the second quote of a scenario -- sword base 100 G reduced by 15 G");
  it.todo("applies the first insurance surcharge to every quote, even a follow-up contract");
  it.todo("applies policy-wide modifiers to the policy base premium, not to the running total");
});

describe("MHPCO quote -- rounding in the MHPCO's favour", () => {
  it.todo("rounds a premium of 197.5 G up to 198 G");
  it.todo("keeps intermediate amounts as fractions and rounds only the final premium");
});

describe("MHPCO quote -- integration examples", () => {
  it.todo("quotes a newcomer's cursed sword at 165 G (100 base + 50 curse + 10 first insurance + 5 fee)");
  it.todo("quotes a long-standing customer's second contract cursed enchanted sword at 160 G");
});

describe("MHPCO claim -- standard reimbursement and deductible", () => {
  it.todo("reimburses a regular steel sword with enchantment 3 damaged 500 G at 400 G (damage minus 100 G deductible)");
  it.todo("reimburses a damaged rune (no enchantment, no material) damaged 200 G at 100 G");
  it.todo("applies the 100 G deductible once per damaged item -- sword 500 G + amulet 300 G yields payout 600 G");
});

describe("MHPCO claim -- special reimbursement clauses", () => {
  it.todo("reimburses damage to an item with enchantment exactly 8 at 50 % -- dragon sword damaged 1000 G yields 400 G");
  it.todo("reimburses dragon-material damage in full -- dragon sword enchantment 5 damaged 800 G yields 700 G");
  it.todo("lets the 50 % high-enchantment rule win over dragon material -- dragon sword enchantment 9 damaged 1000 G yields 400 G");
  it.todo("applies only the high-enchantment clause to a steel sword enchantment 9 damaged 1000 G -- payout 400 G");
});

describe("MHPCO claim -- insurance sum and payout cap", () => {
  it.todo("caps a policy of a sword and an amulet at twice the insurance sum 1600 G -- cap 3200 G");
  it.todo("bases the cap on the unmodified insurance value -- cursed sword premium 165 G still has cap 2000 G");
  it.todo("counts a component block at full insurance value -- sword + 3 runes insurance sum 1750 G");
  it.todo("reports the remaining cap after a claim -- sword cap 2000 G, claim 1500 G yields payout 1400 G and remaining cap 600 G");
  it.todo("reduces a later payout to the remaining cap -- second claim of 1500 G yields payout 600 G and remaining cap 0 G");
});

describe("MHPCO claim -- multiple items of the same type", () => {
  it.todo("insures two swords at insurance sum 2000 G with cap 4000 G");
  it.todo("treats two sword damage entries as separate damages, each with its own deductible");
  it.todo("rejects with an Error a claim with more damage entries of a type than the policy covers");
});

describe("MHPCO claim -- rounding in the MHPCO's favour", () => {
  it.todo("rounds a payout of 350.5 G down to 350 G");
});

describe("MHPCO claim -- rejections", () => {
  it.todo("rejects with an Error a damage to an item type not covered by the policy -- amulet damaged, only a sword insured");
  it.todo("rejects with an Error a damage entry with an unknown item type");
  it.todo("rejects with an Error a damage entry with a negative amount -- amount: -200");
});

describe("claim-office CLI", () => {
  it.todo("reads a scenario from stdin and writes {results} to stdout in step order");
  it.todo("writes a quote result as {premium} and a claim result as {payout, remainingCap}");
  it.todo("resolves a claim's policy field as the zero-based index of the quote step");
  it.todo("exits non-zero and writes an error description to stderr for an unknown item type, writing no results to stdout");
  it.todo("exits non-zero and writes an error description to stderr for a damage outside the policy");
  it.todo("exits non-zero and writes an error description to stderr for a negative damage amount");
});

