const PROCESSING_FEE = 5;
const SWORD_BASE_PREMIUM = 100;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;

export interface Item {
  type: string;
}

export function quote(items: Item[]): number {
  const policyBasePremium = items.length * SWORD_BASE_PREMIUM;
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE);
}
EOF
