const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const COMPONENT_TYPES = ["rune", "moonstone"];

export interface Item {
  type: string;
}

function basePremiumOf(item: Item): number {
  const basePremium = BASE_PREMIUMS[item.type];
  if (basePremium === undefined) {
    throw new Error(`Unknown item type: ${item.type}`);
  }
  return basePremium;
}

function countByType(items: Item[]): Map<string, number> {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
}

function policyBasePremiumOf(items: Item[]): number {
  const counts = countByType(items);
  let total = 0;
  for (const [type, count] of counts) {
    const singleBasePremium = basePremiumOf({ type });
    const isBlock = COMPONENT_TYPES.includes(type) && count === BLOCK_SIZE;
    total += isBlock ? BLOCK_BASE_PREMIUM : count * singleBasePremium;
  }
  return total;
}

export function quote(items: Item[]): number {
  const policyBasePremium = policyBasePremiumOf(items);
  const firstInsuranceSurcharge = policyBasePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return Math.ceil(policyBasePremium + firstInsuranceSurcharge + PROCESSING_FEE);
}
EOF
