input.content:
import { type Incident, type Policy, claim, createPolicy } from "./claim.js";
import { type Customer, type Item, quote } from "./quote.js";

interface QuoteStep {
  op: "quote";
  items: Item[];
}

interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

type Step = QuoteStep | ClaimStep;

interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

type StepResult = { premium: number } | { payout: number; remainingCap: number };

/**
 * Runs a scenario's steps in order for a single customer, carrying the customer's
 * contract history and the policies created by earlier quote steps.
 */
function runScenario(scenario: Scenario): StepResult[] {
  const policiesByStep = new Map<number, Policy>();
  let previousContracts = 0;

  return scenario.steps.map((step, stepIndex) => {
    if (step.op === "quote") {
      const customer: Customer = {
        yearsWithMHPCO: scenario.customer.yearsWithMHPCO,
        previousContracts,
      };
      const premium = quote(step.items, customer);
      previousContracts += 1;
      policiesByStep.set(stepIndex, createPolicy(step.items));
      return { premium };
    }

    const policy = policiesByStep.get(step.policy);
    if (policy === undefined) {
      throw new Error(`Claim refers to step ${step.policy}, which created no policy`);
    }
    return claim(policy, step.incident);
  });
}

function readStdin(): Promise<string> {
  return new Promise((resolve, reject) => {
    let input = "";
    process.stdin.setEncoding("utf8");
    process.stdin.on("data", (chunk) => (input += chunk));
    process.stdin.on("end", () => resolve(input));
    process.stdin.on("error", reject);
  });
}

async function main(): Promise<void> {
  try {
